  13	// A verdict or a run that gave up has already used the agents' own retries, so it fails the item
  14	// at once rather than starting the agents over on the step's next attempt.
  15	export const recipeStep = (ctx: StepContext, domain: string, html: string) =>
  16	  runStep(ctx, STEP.recipe, "generating", "15 minutes", async () => {
  17	    const { env, itemId, instanceId } = ctx;
  18	    const db = database(env.DB);
  19	    const recipe = await getLatestRecipeVersion(db, domain);
  20	    const settled = await settle(env, { instanceId, domain, html, recipe });
  21	
  22	    if (settled.kind === "not-article") {
  23	      throw new NonRetryableError("the page is not an article");
  24	    }
  25	
  26	    if (settled.kind === "gave-up") {
  27	      throw new NonRetryableError(settled.reason);
  28	    }
  29	
  30	    const { units, declaredImages } = toTypedUnits(settled.units);
  31	
  32	    await updateItem(db, itemId, {
  33	      title: settled.title,
  34	      units,
  35	      recipe_version_id:
  36	        settled.versionId ?? (await createRecipeVersion(db, { domain, script: settled.script })).id,
  37	    });
  38	
  39	    return { declaredImages };
  40	  });

