  1	import type { RecipeVersionRow } from "@nagara/common";
  2	import { agentConversation } from "../agents/conversation.ts";
  3	import type { AgentKind } from "../agents/gateway.ts";
  4	import { authorMessage, revisionMessage } from "../agents/prompts.ts";
  5	import { parseSettlement } from "../agents/settlement.ts";
  6	import { runRecipe } from "../runtime/run.ts";
  7	import type { Unit } from "../runtime/units.ts";
  8	
  9	export type SettleRequest = {
 10	  instanceId: string;
 11	  domain: string;
 12	  html: string;
 13	  recipe: RecipeVersionRow | null;
 14	};
 15	
 16	// versionId is null for a script the agents just settled, which is not saved yet.
 17	export type Settled =
 18	  | { kind: "ok"; title: string; units: Unit[]; script: string; versionId: string | null }
 19	  | { kind: "not-article" }
 20	  | { kind: "gave-up"; reason: string };
 21	
 22	type Attempts = {
 23	  agent: AgentKind;
 24	  retries: number;
 25	  message: (report: string[] | null) => string;
 26	  report: string[] | null;
 27	  exhausted: string;
 28	};
 29	
 30	// The conversation is keyed by the Workflow instance alone, so every attempt here, the recipe
 31	// step's own retries and a restart from that step all continue one conversation. Every settled
 32	// script runs through the runtime again: the reply never carries units.
 33	const converge = async (
 34	  env: Cloudflare.Env,
 35	  { instanceId, html, recipe }: SettleRequest,
 36	  attempts: Attempts,
 37	): Promise<Settled> => {
 38	  let report = attempts.report;
 39	
 40	  for (let attempt = 0; attempt <= attempts.retries; attempt += 1) {
 41	    const reply = await agentConversation(attempts.agent, instanceId, attempts.message(report), {
 42	      html,
 43	      recipe: recipe?.script,
 44	    });
 45	    const settlement = parseSettlement(reply);
 46	
 47	    if (settlement.kind === "not-article") {
 48	      return settlement;
 49	    }
 50	
 51	    if (settlement.kind === "script") {
 52	      const run = await runRecipe(env, settlement.source, html);
 53	
 54	      if (run.ok) {
 55	        return {
 56	          kind: "ok",
 57	          title: run.title,
 58	          units: run.units,
 59	          script: settlement.source,
 60	          versionId: null,
 61	        };
 62	      }
 63	
 64	      report = run.report;
 65	    }
 66	  }
 67	
 68	  return { kind: "gave-up", reason: attempts.exhausted };
 69	};
 70	
 71	export const settle = async (env: Cloudflare.Env, request: SettleRequest): Promise<Settled> => {
 72	  const { domain, html, recipe } = request;
 73	
 74	  if (recipe == null) {
 75	    return converge(env, request, {
 76	      agent: "author",
 77	      retries: env.authoringRetries,
 78	      message: (report) => authorMessage(domain, report),
 79	      report: null,
 80	      exhausted: "authoring gave up: nothing is saved for the domain",
 81	    });
 82	  }
 83	
 84	  const run = await runRecipe(env, recipe.script, html);
 85	
 86	  if (run.ok) {
 87	    return {
 88	      kind: "ok",
 89	      title: run.title,
 90	      units: run.units,
 91	      script: recipe.script,
 92	      versionId: recipe.id,
 93	    };
 94	  }
 95	
 96	  return converge(env, request, {
 97	    agent: "revision",
 98	    retries: env.revisionRetries,
 99	    message: (report) => revisionMessage(domain, report ?? run.report, recipe.script),
100	    report: run.report,
101	    exhausted: "revision gave up: the recipe still fails the article and the old version stands",
102	  });
103	};
104	// The recipe key: the host of the fetch's final URL with only a leading www dropped, so subdomains
105	// stay distinct domains and consolidation comes from redirects alone.
106	export const domainFromUrl = (url: string) => new URL(url).hostname.replace(/^www\./, "");
107	import { init } from "@flue/runtime";
108	import type * as v from "valibot";
109	import { Author, type AuthorInitialData } from "./author.ts";
110	import { Revisor, type RevisorInitialData } from "./revisor.ts";
111	
112	export type AgentKind = "author" | "revision";
113	
114	export interface AgentDispatchReceipt {
115	  submissionId: string;
116	  acceptedAt: string;
117	  uid: string;
118	}
119	
120	export interface AgentInitialData {
121	  html: string;
122	  recipe?: string;
123	}
124	
125	function agentFor(kind: AgentKind) {
126	  return kind === "author" ? Author : Revisor;
127	}
128	
129	function initialDataFor(kind: AgentKind, data: AgentInitialData): unknown {
130	  if (kind === "author") {
131	    return { html: data.html } satisfies v.InferOutput<typeof AuthorInitialData>;
132	  }
133	  return { html: data.html, recipe: data.recipe ?? "" } satisfies v.InferOutput<
134	    typeof RevisorInitialData
135	  >;
136	}
137	
138	export async function dispatchAgent(
139	  kind: AgentKind,
140	  conversationId: string,
141	  message: string,
142	  initialData: AgentInitialData,
143	): Promise<AgentDispatchReceipt> {
144	  const handle = init(agentFor(kind), { id: conversationId });
145	  return await handle.dispatch({ message, initialData: initialDataFor(kind, initialData) });
146	}
147	
148	export async function readAgent(
149	  kind: AgentKind,
150	  conversationId: string,
151	  receipt: AgentDispatchReceipt,
152	): Promise<{ text: string }> {
153	  const handle = init(agentFor(kind), { id: conversationId });
154	  const reply = await handle.read(receipt);
155	  return { text: reply.text };
156	}
157	import { type AgentInitialData, type AgentKind, dispatchAgent, readAgent } from "./gateway.ts";
158	
159	export type AgentConversation = (
160	  kind: AgentKind,
161	  conversationId: string,
162	  message: string,
163	  initialData: AgentInitialData,
164	) => Promise<string>;
165	
166	export const agentConversation: AgentConversation = async (
167	  kind,
168	  conversationId,
169	  message,
170	  initialData,
171	) => {
172	  const receipt = await dispatchAgent(kind, conversationId, message, initialData);
173	
174	  return (await readAgent(kind, conversationId, receipt)).text;
175	};
