178	import { env } from "cloudflare:workers";
179	import { useInitialData, useModel } from "@flue/runtime";
180	import * as v from "valibot";
181	import { AGENT_DURABILITY, useExtractTool } from "./extract-tool.ts";
182	import { authorInstruction } from "./prompts.ts";
183	
184	export const AuthorInitialData = v.object({
185	  html: v.string(),
186	});
187	
188	export function Author() {
189	  // Flue defaults the thinking level to "medium"; asking for none is what routes
190	  // the request through the model entry's "off" mapping, the cheapest effort this
191	  // endpoint accepts. Thinking cannot be disabled outright here.
192	  useModel(env.agentModel, { thinkingLevel: "off" });
193	  const { html } = useInitialData<v.InferOutput<typeof AuthorInitialData>>();
194	  useExtractTool(html);
195	  return authorInstruction(env.agentMaxTurns, html);
196	}
197	
198	Author.initialData = AuthorInitialData;
199	Author.durability = AGENT_DURABILITY;
200	"use agent";
201	
202	import { env } from "cloudflare:workers";
203	import { useInitialData, useModel } from "@flue/runtime";
204	import * as v from "valibot";
205	import { AGENT_DURABILITY, useExtractTool } from "./extract-tool.ts";
206	import { revisorInstruction } from "./prompts.ts";
207	
208	export const RevisorInitialData = v.object({
209	  html: v.string(),
210	  recipe: v.string(),
211	});
212	
213	export function Revisor() {
214	  // Flue defaults the thinking level to "medium"; asking for none is what routes
215	  // the request through the model entry's "off" mapping, the cheapest effort this
216	  // endpoint accepts. Thinking cannot be disabled outright here.
217	  useModel(env.agentModel, { thinkingLevel: "off" });
218	  const { html } = useInitialData<v.InferOutput<typeof RevisorInitialData>>();
219	  useExtractTool(html);
220	  return revisorInstruction(env.agentMaxTurns, html);
221	}
222	
223	Revisor.initialData = RevisorInitialData;
224	Revisor.durability = AGENT_DURABILITY;
225	import * as v from "valibot";
226	
227	const settlementSchema = v.variant("kind", [
228	  v.object({
229	    kind: v.literal("script"),
230	    source: v.pipe(v.string(), v.minLength(1)),
231	  }),
232	  v.object({ kind: v.literal("not-article") }),
233	  v.object({
234	    kind: v.literal("gave-up"),
235	    reason: v.optional(v.string(), "no reason given"),
236	  }),
237	]);
238	
239	export type Settlement = v.InferOutput<typeof settlementSchema>;
240	
241	function parseJson(text: string): unknown {
242	  try {
243	    return JSON.parse(text);
244	  } catch {
245	    return null;
246	  }
247	}
248	
249	export function parseSettlement(text: string): Settlement {
250	  const fenced = [...text.matchAll(/```[a-zA-Z]*\n?([\s\S]*?)```/g)];
251	  for (const block of fenced.reverse()) {
252	    const parsed = v.safeParse(settlementSchema, parseJson(block[1].trim()));
253	    if (parsed.success) {
254	      return parsed.output;
255	    }
256	  }
257	  const whole = v.safeParse(settlementSchema, parseJson(text.trim()));
258	  if (whole.success) {
259	    return whole.output;
260	  }
261	  return { kind: "gave-up", reason: "the reply carried no readable settlement" };
262	}
263	
264	export function scriptReply(source: string): string {
265	  return `\`\`\`json\n${JSON.stringify({ kind: "script", source })}\n\`\`\``;
266	}
