270	import { runRecipe } from "../runtime/run.ts";
271	
272	export const AGENT_DURABILITY = { maxAttempts: 5, timeoutMs: 1_800_000 };
273	
274	export function useExtractTool(html: string): void {
275	  useTool({
276	    name: "extract",
277	    description:
278	      "Run a candidate recipe against the article and return its extraction result or its validation report.",
279	    input: v.object({ recipe: v.string() }),
280	    output: undefined,
281	    async run({ data }) {
282	      return { output: await runRecipe(env, data.recipe, html) };
283	    },
284	  });
285	}

  1	import type { WorkflowStep, WorkflowStepConfig } from "cloudflare:workers";
  2	import { database, type ItemStatus, type Step, writeStatus } from "@nagara/common";
  3	
  4	export type StepContext = {
  5	  step: WorkflowStep;
  6	  env: Cloudflare.Env;
  7	  itemId: string;
  8	  instanceId: string;
  9	};
 10	
 11	// The limit counts retries, not attempts: 2 gives each step the three attempts the item lifecycle
 12	// promises.
 13	export const STEP_RETRIES: WorkflowStepConfig["retries"] = {
 14	  limit: 2,
 15	  delay: "5 seconds",
 16	  backoff: "exponential",
 17	};
 18	
 19	// step.do rethrows a NonRetryableError as a plain Error whose message carries the class name; the
 20	// row keeps the step's own words.
 21	const messageOf = (error: unknown) =>
 22	  (error instanceof Error ? error.message : String(error)).replace(/^NonRetryableError: /, "");
 23	
 24	export const failStep = async ({ step, env, itemId }: StepContext, name: Step, error: unknown) => {
 25	  await step.do(`${name} failed`, async () => {
 26	    await writeStatus(database(env.DB), itemId, {
 27	      status: "failed",
 28	      currentStep: name,
 29	      error: messageOf(error),
 30	    });
 31	  });
 32	};
 33	
 34	// The status write happens inside every attempt, so a restart from this step writes it again and
 35	// clears the error the failed run left. An attempt that fails with attempts left writes nothing,
 36	// so the row never shows failed while the step still retries.
 37	export const runStep = async <T extends Rpc.Serializable<T>>(
 38	  ctx: StepContext,
 39	  name: Step,
 40	  status: Extract<ItemStatus, "queued" | "generating">,
 41	  timeout: WorkflowStepConfig["timeout"],
 42	  body: () => Promise<T>,
 43	) => {
 44	  try {
 45	    return await ctx.step.do(name, { retries: STEP_RETRIES, timeout }, async () => {
 46	      await writeStatus(database(ctx.env.DB), ctx.itemId, { status, currentStep: name });
 47	
 48	      return body();
 49	    });
 50	  } catch (error) {
 51	    await failStep(ctx, name, error);
 52	
 53	    throw error;
 54	  }
 55	};
 56	import { WorkflowEntrypoint, type WorkflowEvent, type WorkflowStep } from "cloudflare:workers";
 57	import type { ItemWorkflowParams } from "@nagara/common";
 58	import { describeStep } from "./steps/describe.ts";
 59	import { fetchStep } from "./steps/fetch.ts";
 60	import { imagesStep } from "./steps/images.ts";
 61	import { leaseStep, releaseStep } from "./steps/lease.ts";
 62	import { recipeStep } from "./steps/recipe.ts";
 63	import { startSynthesisStep, storeStep, waitForSynthesisStep } from "./steps/synthesis.ts";
 64	import type { StepContext } from "./wrapper.ts";
 65	
 66	// The order is required throughout: the lease covers exactly the recipe, images come before
 67	// describe because describe reads the stored images, and describe comes before synthesis because
 68	// synthesis reads the described spoken forms from the row.
 69	export class ItemWorkflow extends WorkflowEntrypoint<Cloudflare.Env, ItemWorkflowParams> {
 70	  async run(event: WorkflowEvent<ItemWorkflowParams>, step: WorkflowStep) {
 71	    const ctx: StepContext = {
 72	      step,
 73	      env: this.env,
 74	      itemId: event.payload.itemId,
 75	      instanceId: event.instanceId,
 76	    };
 77	
 78	    const { html, domain } = await fetchStep(ctx);
 79	
 80	    await leaseStep(ctx, domain);
 81	
 82	    const { declaredImages } = await recipeStep(ctx, domain, html);
 83	
 84	    await releaseStep(ctx, domain);
 85	
 86	    await imagesStep(ctx, declaredImages);
 87	    await describeStep(ctx);
 88	
 89	    const { callId } = await startSynthesisStep(ctx);
 90	    const result = await waitForSynthesisStep(ctx, callId);
 91	
 92	    await storeStep(ctx, result);
 93	  }
 94	}
 95	import { describeError } from "../errors.ts";
 96	import { INJECTION_BUNDLE_SOURCE } from "../generated/injection-bundle.ts";
 97	import { RUNTIME_MODULE } from "./glue.ts";
 98	import type { ExecutionPayload, RecipeRun } from "./recipe.ts";
 99	import { toBoundaryUnit } from "./units.ts";
100	import { validateExtraction } from "./validate.ts";
101	
102	const DYNAMIC_COMPAT_DATE = "2026-09-01";
103	
104	export class PlatformFailure extends Error {
105	  constructor(message: string, cause?: unknown) {
106	    super(message);
107	    this.name = "PlatformFailure";
108	    this.cause = cause;
109	  }
110	}
111	
112	export async function executeInDynamicWorker(
113	  env: Cloudflare.Env,
114	  recipeSource: string,
115	  html: string,
116	  options?: { injectionSource?: string },
117	): Promise<ExecutionPayload> {
118	  let worker: ReturnType<Cloudflare.Env["LOADER"]["load"]>;
119	  try {
120	    worker = env.LOADER.load({
121	      compatibilityDate: DYNAMIC_COMPAT_DATE,
122	      mainModule: "runtime.js",
123	      modules: {
124	        "runtime.js": { js: RUNTIME_MODULE },
125	        "injection.js": { js: options?.injectionSource ?? INJECTION_BUNDLE_SOURCE },
126	        "recipe.js": { js: recipeSource },
127	      },
128	      limits: { cpuMs: env.recipeCpuMs },
129	      globalOutbound: null,
130	    });
131	  } catch (error) {
132	    throw new PlatformFailure(`the recipe runtime did not load: ${describeError(error)}`, error);
133	  }
134	
135	  // The health probe separates the two platform failures (an unreachable
136	  // dynamic worker, a bundle that does not load) from anything the recipe
137	  // itself does: the probe runs no recipe code, so its failure is the
138	  // platform's — and a recipe that does not parse reports itself as data on
139	  // the probe's answer, so a load failure never masquerades as a platform
140	  // one.
141	  try {
142	    const probe = await worker.getEntrypoint().fetch(new Request("https://runtime/health"));
143	    if (!probe.ok) {
144	      throw new Error(`the health probe answered ${probe.status}`);
145	    }
146	    const health = (await probe.json()) as { ok: boolean; recipeError?: string };
147	    if (!health.ok) {
148	      return {
149	        ok: false,
150	        report: [`the recipe module does not load: ${health.recipeError ?? "no details"}`],
151	      };
152	    }
153	  } catch (error) {
154	    // A module that does not parse never starts the worker, so no handler can
155	    // report it as data and the platform's error is all there is to read: it names
156	    // `recipe.js` in some runtimes and raises a bare SyntaxError in others. The
157	    // bundle's own modules fail to link the same way, so a SyntaxError belongs to
158	    // the recipe only when it names neither of them. Getting this wrong tells the
159	    // agent the runtime is broken and it stops rewriting the recipe.
160	    const description = describeError(error);
161	    const namesPlatformModule = /runtime\.js|injection\.js/.test(description);
162	    if (
163	      /recipe\.js/.test(description) ||
164	      (/SyntaxError/.test(description) && !namesPlatformModule)
165	    ) {
166	      return {
167	        ok: false,
168	        report: [`the recipe module does not load: ${description}`],
169	      };
170	    }
171	    throw new PlatformFailure(`the dynamic worker is unreachable: ${description}`, error);
172	  }
173	
174	  try {
175	    const response = await worker.getEntrypoint().fetch(
176	      new Request("https://runtime/extract", {
177	        method: "POST",
