  2	import { database, type ItemStatus, type Step, writeStatus } from "@nagara/common";
  3	
  4	export type StepContext = {
  5	  step: WorkflowStep;
  6	  env: Cloudflare.Env;
  7	  itemId: string;
  8	  instanceId: string;
  9	};
 10	
 11	// The limit counts retries, not attempts: 2 gives each step the three attempts the item lifecycle
 12	// promises.
 13	export const STEP_RETRIES: WorkflowStepConfig["retries"] = {
 14	  limit: 2,
 15	  delay: "5 seconds",
 16	  backoff: "exponential",
 17	};
 18	
 19	// step.do rethrows a NonRetryableError as a plain Error whose message carries the class name; the
 20	// row keeps the step's own words.
 21	const messageOf = (error: unknown) =>
 22	  (error instanceof Error ? error.message : String(error)).replace(/^NonRetryableError: /, "");
 23	
 24	export const failStep = async ({ step, env, itemId }: StepContext, name: Step, error: unknown) => {
 25	  await step.do(`${name} failed`, async () => {
 26	    await writeStatus(database(env.DB), itemId, {
 27	      status: "failed",
 28	      currentStep: name,
 29	      error: messageOf(error),
 30	    });
 31	  });
 32	};
 33	
 34	// The status write happens inside every attempt, so a restart from this step writes it again and
 35	// clears the error the failed run left. An attempt that fails with attempts left writes nothing,
 36	// so the row never shows failed while the step still retries.
 37	export const runStep = async <T extends Rpc.Serializable<T>>(
 38	  ctx: StepContext,
 39	  name: Step,
 40	  status: Extract<ItemStatus, "queued" | "generating">,
 41	  timeout: WorkflowStepConfig["timeout"],
 42	  body: () => Promise<T>,
 43	) => {
 44	  try {
 45	    return await ctx.step.do(name, { retries: STEP_RETRIES, timeout }, async () => {
 46	      await writeStatus(database(ctx.env.DB), ctx.itemId, { status, currentStep: name });
 47	
 48	      return body();
 49	    });
 50	  } catch (error) {
 51	    await failStep(ctx, name, error);
 52	
 53	    throw error;
 54	  }
 55	};
 56	import { WorkflowEntrypoint, type WorkflowEvent, type WorkflowStep } from "cloudflare:workers";
 57	import type { ItemWorkflowParams } from "@nagara/common";
 58	import { describeStep } from "./steps/describe.ts";
 59	import { fetchStep } from "./steps/fetch.ts";
