 65	
 66	// The order is required throughout: the lease covers exactly the recipe, images come before
 67	// describe because describe reads the stored images, and describe comes before synthesis because
 68	// synthesis reads the described spoken forms from the row.
 69	export class ItemWorkflow extends WorkflowEntrypoint<Cloudflare.Env, ItemWorkflowParams> {
 70	  async run(event: WorkflowEvent<ItemWorkflowParams>, step: WorkflowStep) {
 71	    const ctx: StepContext = {
 72	      step,
 73	      env: this.env,
 74	      itemId: event.payload.itemId,
 75	      instanceId: event.instanceId,
 76	    };
 77	
 78	    const { html, domain } = await fetchStep(ctx);
 79	
 80	    await leaseStep(ctx, domain);
 81	
 82	    const { declaredImages } = await recipeStep(ctx, domain, html);
 83	
 84	    await releaseStep(ctx, domain);
 85	
 86	    await imagesStep(ctx, declaredImages);
 87	    await describeStep(ctx);
 88	
 89	    const { callId } = await startSynthesisStep(ctx);
 90	    const result = await waitForSynthesisStep(ctx, callId);
