 95	import { describeError } from "../errors.ts";
 96	import { INJECTION_BUNDLE_SOURCE } from "../generated/injection-bundle.ts";
 97	import { RUNTIME_MODULE } from "./glue.ts";
 98	import type { ExecutionPayload, RecipeRun } from "./recipe.ts";
 99	import { toBoundaryUnit } from "./units.ts";
100	import { validateExtraction } from "./validate.ts";
101	
102	const DYNAMIC_COMPAT_DATE = "2026-09-01";
103	
104	export class PlatformFailure extends Error {
105	  constructor(message: string, cause?: unknown) {
106	    super(message);
107	    this.name = "PlatformFailure";
108	    this.cause = cause;
109	  }
110	}
111	
112	export async function executeInDynamicWorker(
113	  env: Cloudflare.Env,
114	  recipeSource: string,
115	  html: string,
116	  options?: { injectionSource?: string },
117	): Promise<ExecutionPayload> {
118	  let worker: ReturnType<Cloudflare.Env["LOADER"]["load"]>;
119	  try {
120	    worker = env.LOADER.load({
121	      compatibilityDate: DYNAMIC_COMPAT_DATE,
122	      mainModule: "runtime.js",
123	      modules: {
124	        "runtime.js": { js: RUNTIME_MODULE },
125	        "injection.js": { js: options?.injectionSource ?? INJECTION_BUNDLE_SOURCE },
126	        "recipe.js": { js: recipeSource },
127	      },
128	      limits: { cpuMs: env.recipeCpuMs },
129	      globalOutbound: null,
130	    });
131	  } catch (error) {
132	    throw new PlatformFailure(`the recipe runtime did not load: ${describeError(error)}`, error);
133	  }
134	
135	  // The health probe separates the two platform failures (an unreachable
136	  // dynamic worker, a bundle that does not load) from anything the recipe
137	  // itself does: the probe runs no recipe code, so its failure is the
138	  // platform's — and a recipe that does not parse reports itself as data on
139	  // the probe's answer, so a load failure never masquerades as a platform
140	  // one.
141	  try {
142	    const probe = await worker.getEntrypoint().fetch(new Request("https://runtime/health"));
143	    if (!probe.ok) {
144	      throw new Error(`the health probe answered ${probe.status}`);
145	    }
146	    const health = (await probe.json()) as { ok: boolean; recipeError?: string };
147	    if (!health.ok) {
148	      return {
149	        ok: false,
150	        report: [`the recipe module does not load: ${health.recipeError ?? "no details"}`],
151	      };
152	    }
153	  } catch (error) {
154	    // A module that does not parse never starts the worker, so no handler can
155	    // report it as data and the platform's error is all there is to read: it names
156	    // `recipe.js` in some runtimes and raises a bare SyntaxError in others. The
157	    // bundle's own modules fail to link the same way, so a SyntaxError belongs to
158	    // the recipe only when it names neither of them. Getting this wrong tells the
159	    // agent the runtime is broken and it stops rewriting the recipe.
160	    const description = describeError(error);
161	    const namesPlatformModule = /runtime\.js|injection\.js/.test(description);
162	    if (
163	      /recipe\.js/.test(description) ||
164	      (/SyntaxError/.test(description) && !namesPlatformModule)
165	    ) {
166	      return {
167	        ok: false,
168	        report: [`the recipe module does not load: ${description}`],
169	      };
170	    }
171	    throw new PlatformFailure(`the dynamic worker is unreachable: ${description}`, error);
172	  }
173	
174	  try {
175	    const response = await worker.getEntrypoint().fetch(
176	      new Request("https://runtime/extract", {
177	        method: "POST",
178	        headers: { "content-type": "application/json" },
179	        body: JSON.stringify({ html }),
180	      }),
181	    );
182	    if (!response.ok) {
183	      throw new PlatformFailure(`the recipe runtime answered ${response.status}`);
184	    }
185	    return (await response.json()) as ExecutionPayload;
186	  } catch (error) {
187	    if (error instanceof PlatformFailure) {
188	      throw error;
189	    }
190	    return {
191	      ok: false,
192	      report: [`the recipe died during execution: ${describeError(error)}`],
193	    };
194	  }
195	}
196	
197	export async function runRecipe(
198	  env: Cloudflare.Env,
199	  recipeSource: string,
200	  html: string,
201	): Promise<RecipeRun> {
202	  const execution = await executeInDynamicWorker(env, recipeSource, html);
203	  if (!execution.ok) {
204	    return { ok: false, report: execution.report };
205	  }
206	  const report = validateExtraction(execution.extraction, html);
207	  if (report.length > 0) {
208	    return { ok: false, report };
209	  }
210	  const { title, units } = execution.extraction;
211	  return { ok: true, title, units: units.map(toBoundaryUnit) };
212	}
213	import type { Model, Provider } from "@earendil-works/pi-ai";
214	import { createProvider } from "@earendil-works/pi-ai";
215	import { anthropicMessagesApi } from "@earendil-works/pi-ai/api/anthropic-messages.lazy";
216	import { openAICompletionsApi } from "@earendil-works/pi-ai/api/openai-completions.lazy";
217	import { openAIResponsesApi } from "@earendil-works/pi-ai/api/openai-responses.lazy";
218	import { CLOUDFLARE_AI_GATEWAY_MODELS } from "@earendil-works/pi-ai/providers/cloudflare-ai-gateway.models";
219	import { cloudflareAIGatewayAuth } from "@earendil-works/pi-ai/providers/cloudflare-auth";
220	import { cloudflareStreams } from "@earendil-works/pi-ai/providers/cloudflare-stream";
221	
222	export const GLM_5_3_FLASH_ID = "workers-ai/@cf/zai-org/glm-5.3-flash";
223	
224	// The shipped entry is right about everything except the two bounds the endpoint
225	// actually enforces and the reasoning knob it actually honours.
226	function withMeasuredMetadata(model: Model<"openai-completions">): Model<"openai-completions"> {
227	  return {
228	    ...model,
229	    // The catalog carries the window the model's docs page advertises, 1,310,720, but
230	    // the endpoint rejects anything past 1,048,576 for input and completion combined.
231	    contextWindow: 1_048_576,
232	    // The catalog sets this to the advertised completion cap, which only works for the
233	    // small-window entries. pi-ai sizes each request as min(maxTokens, contextWindow -
234	    // prompt - 4096), so a million-token budget has the model answering for minutes.
235	    maxTokens: 131_072,
236	    // Thinking cannot be switched off on this route and defaults to maximum effort, so
237	    // a turn costs minutes and thousands of tokens. `reasoning_effort` is the one lever
238	    // the endpoint honours, and pi-ai sends `off`'s mapping when an agent asks for no
239	    // particular level: mapping it to "low" is what makes the default turn cheap. The
240	    // higher levels map to their own names so tuning stays a change to this table.
241	    thinkingLevelMap: {
242	      off: "low",
243	      low: "low",
244	      medium: "medium",
245	      high: "high",
246	      xhigh: "xhigh",
247	      max: "max",
248	    },
249	    // The catalog marks the whole gateway as not supporting the parameter, which is
250	    // what keeps pi-ai from sending it; this route does support it.
251	    compat: { ...model.compat, supportsReasoningEffort: true },
252	  };
253	}
254	
255	export function agentModelProvider(): Provider {
256	  const models = Object.values(CLOUDFLARE_AI_GATEWAY_MODELS).map((model) =>
257	    model.id === GLM_5_3_FLASH_ID ? withMeasuredMetadata(model) : model,
258	  );
259	
260	  return createProvider({
261	    id: "cloudflare-ai-gateway",
262	    name: "Cloudflare AI Gateway",
263	    auth: { apiKey: cloudflareAIGatewayAuth() },
264	    models,
265	    api: {
266	      "anthropic-messages": cloudflareStreams(anthropicMessagesApi()),
267	      "openai-completions": cloudflareStreams(openAICompletionsApi()),
268	      "openai-responses": cloudflareStreams(openAIResponsesApi()),
269	    },
270	  });
271	}

